mapper.select:
SELECT T.* FROM (SELECT E.*, C.ORGNAME AS USEDDEPARTMENTNAME, O.ORGNAME AS USEDDEPOSTNAME, U.USERNAME AS MAINTAINUSERNAME, S.USERNAME AS KEEPUSERNAME FROM T_EMC_EQUIPT E LEFT JOIN T_CORE_ORG C ON E.USEDDEPARTMENTID = C.ID LEFT JOIN T_CORE_ORG O ON E.USEDDEPOSTID = C.ID LEFT JOIN T_CORE_USER U ON E.MAINTAINUSERID = U.ID LEFT JOIN T_CORE_USER S ON E.KEEPUSERID = S.ID) T
AND NOT EXISTS (SELECT 1 FROM ${targetTable} TAR_ WHERE TAR_.${targetEquiptColumn} = T.ID
AND TAR_.${targetFilterColumn} = #{targetFilterValue}
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
AND EXISTS ( SELECT 1 FROM T_EMC_EQUIPT_TEST_METHOD F WHERE F.EQUIPTID = T.ID AND F.ANALYSISCATEGORY = 'sampling' AND F.TESTMETHODID = #{item} )
AND EXISTS( SELECT 1 FROM T_EMC_EQUIPT_PLAN TAR_ WHERE TAR_.EQUIPTID = T.ID AND TAR_.MAINTENDDATE <= GETDATE() + TAR_.WARNINGDAYS )
AND EXISTS ( SELECT 1 FROM T_EMC_EQUIPT_TEST_METHOD E, t_emc_order_task OT, t_emc_order O, T_EMC_EQUIPT_CATEGORY C WHERE O.ID = OT.ORDERID AND OT.TESTMETHODID = E.TESTMETHODID AND E.EQUIPTID = T.ID AND C.ID = T.EQUIPTCATEGORYID AND C.EQUIPTCATEGORY = '现场' AND O.FOLDERID = #{folderid} )
ORDER BY
T.ID DESC
